 useEffect(()=>{const prev=prevPanelStatus.current;prevPanelStatus.current=panel?.status;if(!individual||tab!=='panels'||!panel||!prev)return;if(!activeStatuses.includes(prev)||activeStatuses.includes(panel.status))return;if(panel.status==='PASS')navigate(drawingPath(projectId,panel.id,'viewer'));else if(panel.status==='NEEDS_REVIEW')navigate(drawingPath(projectId,panel.id,'review'));},[panel?.status]);
