useEffect(()=>{if(!individual||!panel||tab!=='panels'||activeStatuses.includes(panel.status))return;navigate(drawingPath(projectId,panel.id,panel.status==='PASS'?'viewer':'review'));},[panel?.id]);// eslint-disable-line react-hooks/exhaustive-deps
