 const visibleSteps:readonly string[]=['panels','review','viewer'];
 const canStep=(step:string)=>step==='panels'?!!panel:step==='review'?!!panel&&(panel.artifacts.includes('extraction.svg')||!activeStatuses.includes(panel.status)):!!panel&&panel.artifacts.includes('panel.glb');
 const visibleStepIndex=visibleSteps.indexOf(tab);const inAssembly=tab==='assembly';const step1Done=visibleStepIndex>0||inAssembly;const step2Done=visibleStepIndex>1||inAssembly;const step3Done=inAssembly;
 function editProject(){if(!project)return;setDialogProjectId(project.id);setName(project.name);setClient(project.client);setDialog('edit_project')}
