 {dialog==='upload'&&<><input ref={input} type="file" accept=".dxf,.dwg" multiple className="sr-only" onChange={e=>{addFiles(Array.from(e.target.files||[]));e.target.value=''}}/><button className={'modal-drop '+(drag?'drag-active':'')} onClick={()=>input.current?.click()} onDragOver={e=>{e.preventDefault();setDrag(true)}} onDragLeave={()=>setDrag(false)} onDrop={e=>{e.preventDefault();setDrag(false);addFiles(Array.from(e.dataTransfer.files))}}><Upload size={30}/><strong>Drop your drawings here</strong><span>or click to browse · DWG / DXF · maximum 10 files per batch · {data.capabilities.max_upload_mb} MB each</span></button>{files.length>0&&<p className="batch-count-line">{files.length} / 10 files selected</p>}<div className="upload-file-list">{files.map((f,i)=><div key={i}><FileText size={16}/><span>{f.name}<small>{(f.size/1024).toFixed(0)} KB</small></span><button aria-label={'Remove '+f.name} onClick={()=>setFiles(v=>v.filter((_,j)=>j!==i))}><X size={15}/></button></div>)}</div>{!data.capabilities.dwg&&files.some(f=>/\.dwg$/i.test(f.name))&&<div className="dialog-notice">DWG files will need review until ODA File Converter is installed on the worker. DXF conversion is available with the Python service.</div>}{!live&&<div className="dialog-notice">Uploads are unavailable in the sample workspace. Connect the Python service to process your own drawings.</div>}<Button disabled={!live||!files.length||busy||!dialogProject} onClick={upload}>{busy?<LoaderCircle className="spin"/>:<Upload/>}Upload {files.length||''} drawing{files.length===1?'':'s'}</Button></>}
